"""Mock OTLP HTTP server that captures all incoming spans.

Listens on 127.0.0.1:4318 by default and stores the decoded JSON bodies
plus the raw protobuf payloads under /tmp/otlp_capture/.
"""
import json
import os
import sys
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer

CAPTURE_DIR = "/tmp/otlp_capture"
os.makedirs(CAPTURE_DIR, exist_ok=True)

# Lazily import the OTLP protobuf decoder.
try:
    from opentelemetry.proto.collector.trace.v1 import trace_service_pb2
except Exception as e:  # pragma: no cover - hard failure if proto missing
    print(f"Failed to import OTLP protobuf: {e}", file=sys.stderr)
    raise


_lock = threading.Lock()
_request_index = {"n": 0}


class Handler(BaseHTTPRequestHandler):
    def do_POST(self):  # noqa: N802 - required by BaseHTTPRequestHandler
        length = int(self.headers.get("Content-Length", "0"))
        body = self.rfile.read(length)
        with _lock:
            _request_index["n"] += 1
            idx = _request_index["n"]

        # Try to decode as protobuf
        decoded_spans = []
        try:
            req = trace_service_pb2.ExportTraceServiceRequest()
            req.ParseFromString(body)
            for rs in req.resource_spans:
                resource_attrs = {}
                for kv in rs.resource.attributes:
                    resource_attrs[kv.key] = _decode_any(kv.value)
                for ss in rs.scope_spans:
                    for span in ss.spans:
                        attrs = {}
                        for kv in span.attributes:
                            attrs[kv.key] = _decode_any(kv.value)
                        events = []
                        for event in span.events:
                            ev_attrs = {}
                            for kv in event.attributes:
                                ev_attrs[kv.key] = _decode_any(kv.value)
                            events.append(
                                {
                                    "name": event.name,
                                    "time_unix_nano": event.time_unix_nano,
                                    "attributes": ev_attrs,
                                }
                            )
                        decoded_spans.append(
                            {
                                "trace_id": span.trace_id.hex(),
                                "span_id": span.span_id.hex(),
                                "parent_span_id": (
                                    span.parent_span_id.hex()
                                    if span.parent_span_id
                                    else ""
                                ),
                                "name": span.name,
                                "kind": span.kind,
                                "start_time_unix_nano": span.start_time_unix_nano,
                                "end_time_unix_nano": span.end_time_unix_nano,
                                "attributes": attrs,
                                "events": events,
                                "status": {"code": span.status.code},
                                "resource_attributes": resource_attrs,
                            }
                        )
        except Exception as e:
            decoded_spans = [{"decode_error": str(e)}]

        out = {
            "path": self.path,
            "headers": {k: v for k, v in self.headers.items()},
            "raw_bytes": len(body),
            "decoded_spans": decoded_spans,
        }

        path = os.path.join(CAPTURE_DIR, f"req_{idx:04d}.json")
        with open(path, "w") as f:
            json.dump(out, f, indent=2, default=str)

        # OTLP expects 200 with empty ExportTraceServiceResponse on success.
        resp = trace_service_pb2.ExportTraceServiceResponse()
        resp_bytes = resp.SerializeToString()
        self.send_response(200)
        self.send_header("Content-Type", "application/x-protobuf")
        self.send_header("Content-Length", str(len(resp_bytes)))
        self.end_headers()
        self.wfile.write(resp_bytes)

    def log_message(self, fmt, *args):  # silence default logging
        return


def _decode_any(any_value):
    """Best-effort decode of opentelemetry.proto.common.v1.AnyValue."""
    kind = any_value.WhichOneof("value")
    if kind == "string_value":
        return any_value.string_value
    if kind == "bool_value":
        return any_value.bool_value
    if kind == "int_value":
        return any_value.int_value
    if kind == "double_value":
        return any_value.double_value
    if kind == "array_value":
        return [_decode_any(v) for v in any_value.array_value.values]
    if kind == "kvlist_value":
        return {
            kv.key: _decode_any(kv.value) for kv in any_value.kvlist_value.values
        }
    if kind is None:
        return None
    return f"<{kind}>"


def main():
    host = sys.argv[1] if len(sys.argv) > 1 else "127.0.0.1"
    port = int(sys.argv[2]) if len(sys.argv) > 2 else 4318
    server = HTTPServer((host, port), Handler)
    print(f"OTLP mock server listening on http://{host}:{port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()

